// Your partner's name, filled in when the template is added.
const PARTNER = {{partner}};
const PLUM = '#2a2350';
const LILAC = '#ece8ff';
const LAVENDER = '#d2c6ff';
const SPARK = 'M12 2l2.2 7.8L22 12l-7.8 2.2L12 22l-2.2-7.8L2 12l7.8-2.2z';
// Until the day's question has arrived, one from this list, picked by the date so both of you see the same one.
const QUESTIONS = [
  'What tiny thing did I do this week that you loved?',
  'What is a smell that takes you straight back to being a kid?',
  'Which day of ours would you live again, start to finish?',
  'What is something you want us to try this year?',
  'When did you last feel really proud of me?',
  'What song should be playing when we walk into a room?',
  'What is a small habit of mine you secretly like?',
  'Where would you take me for a perfect lazy Sunday?',
  'What did you want to be when you were seven?',
  'What is one thing I could do this week to make your day easier?',
  'Which meal of ours would you order again tonight?',
  'What is a dream you have not told many people?',
  'What made you laugh hardest this month?',
  'What is your favourite thing about our home?',
  'If we had a free day tomorrow, how would you spend it?',
  'What is a place you want us to see together?',
  'What do you think I worry about too much?',
  'Which photo of us do you love most, and why?',
  'What did your parents do that you want us to keep doing?',
  'What would your perfect birthday look like?',
  'What is the best advice you have ever been given?',
  'What do I do that makes you feel looked after?',
  'Which friend of ours would you call in a crisis?',
  'What is a skill you would love to learn with me?',
  'What were you most nervous about when we first met?',
  'What is a book, show or film you want me to see?',
  'What is one thing you would like more of in our week?',
  'What do you remember most about our first trip?',
  'What tradition should we start?',
  'What is the kindest thing a stranger has done for you?',
  'What part of your day do you look forward to most?',
  'What do you hope we are doing in ten years?',
  'What is something you are grateful for today?',
  'Which season suits us best, and why?',
  'What is a tiny luxury you would never give up?',
  'When do you feel most like yourself?',
  'What is a compliment you still remember?',
  'What should we celebrate that we never do?',
  'What is your earliest memory of me?',
  'What is a fear you have got over?',
  'What would you cook if you had all day?',
  'What is one thing we do better than anyone?',
  'What three words would you use for this year so far?',
  'What made you choose me?',
  'What is a small adventure we could have this weekend?',
  'What is something you changed your mind about recently?',
  'Which of my friends do you like best?',
  'What do you want to say thank you for this week?',
  'What is a place that feels like home to you, besides home?',
  'What is the silliest argument we have ever had?',
  'What are you looking forward to this month?',
  'What is a quality of mine you hope rubs off on you?',
  'What would our perfect holiday house have?',
  'What is something you would love me to ask you about more?',
  'What did you love about your childhood bedroom?',
  'What is a goal you want us to cheer each other on for?',
  'What is your favourite way to be comforted?',
  'Which moment this year are you proudest of?',
  'What little thing should I never stop doing?',
  'What would you write in a note to us a year from now?',
];

function dayNumber(date) {
  return Math.round(new Date(date) / 86400000);
}

// A key's fill sits twice when it is on: solid in the backdrop, which tinted and clear mode remove, and faint in
// the tree with its words, so in tinted mode the words still show.
function keys(d, u, wide, ghost) {
  const key = (label, on, action, rowId) => {
    const face = { type: 'zstack', padding: { vertical: 6 * u, horizontal: 10 * u },
      background: { type: 'rect', cornerRadius: 10 * u,
        fill: ghost ? (on ? LAVENDER : '#d2c6ff00') : on ? '#d2c6ff40' : '#FFFFFF21' },
      children: [
        { type: 'text', value: label, size: 12 * u, weight: 'bold', color: on ? PLUM : LILAC, lineLimit: 1,
          minScale: 0.3, opacity: ghost ? 0 : 1 } ] };
    return action && !ghost ? { type: 'button', action, rowId, children: [face] } : face;
  };
  return { type: 'hstack', spacing: 7 * u, padding: { leading: 16 * u, trailing: 16 * u, bottom: 14 * u },
    frame: { maxWidth: 'infinity', maxHeight: 'infinity', alignment: 'bottomLeading' },
    children: [
      wide && key(d.theirs ? PARTNER + ' answered' : 'Ask ' + PARTNER + ' too', !!d.theirs),
      d.mine ? key('You answered', true, 'unanswer', d.mine.id) : key('I answered', false, 'answer'),
      { type: 'spacer', minLength: 0 },
      wide && d.mine && !ghost && { type: 'text', value: 'New one tomorrow', size: 11.5 * u, weight: 'semibold',
        color: LILAC, opacity: 0.7, lineLimit: 1, minScale: 0.8 },
    ] };
}

function render(ctx) {
  // Sizes are in the prototype's units: a widget is 170 of them tall. Bricolage's line is 1.2 times its size
  // where the question sets 1.08, so its gap above is a little shorter than the prototype's.
  const u = ctx.height / 170;
  const d = ctx.data;
  const wide = ctx.family === 'medium';
  const n = QUESTIONS.length;
  const question = d.question && d.question.question ? d.question.question
    : QUESTIONS[((dayNumber(ctx.today.date) % n) + n) % n];

  return {
    type: 'zstack', align: 'topLeading',
    frame: { maxWidth: 'infinity', maxHeight: 'infinity' },
    widgetBackground: { type: 'zstack', frame: { maxWidth: 'infinity', maxHeight: 'infinity' }, background: PLUM,
      children: [keys(d, u, wide, true)] },
    children: [
      { type: 'vstack', align: 'leading', spacing: 0, padding: { top: 15 * u, leading: 16 * u, trailing: 16 * u },
        frame: { maxWidth: 'infinity', maxHeight: 'infinity', alignment: 'topLeading' },
        children: [
          { type: 'hstack', spacing: 5 * u, frame: { height: 16 * u }, children: [
            { type: 'path', d: SPARK, viewBox: [0, 0, 24, 24], fill: LAVENDER, frame: { width: 15 * u, height: 15 * u } },
            { type: 'text', value: "Today's question", size: 13 * u, weight: 'bold', color: LAVENDER, lineLimit: 1,
              minScale: 0.8 } ] },
          { type: 'text', value: question, fontName: 'Bricolage Grotesque Key', size: (wide ? 21 : 17) * u,
            kerning: -0.42 * u, color: LILAC, accent: true, lineLimit: wide ? 2 : 3, minScale: 0.75,
            padding: { top: 7.5 * u }, frame: { maxWidth: (ctx.width - 32 * u) * 0.92, alignment: 'leading' } },
          !wide && { type: 'text', value: d.theirs ? PARTNER + ' answered' : 'Ask ' + PARTNER + ' too', size: 11.5 * u,
            weight: 'semibold', color: LILAC, opacity: 0.7, lineLimit: 1, minScale: 0.4, padding: { top: 4 * u } },
        ] },
      keys(d, u, wide, false),
    ],
  };
}
